export const studyDetails = Object.fromEntries(entries.trim().split('\n').map(line => {
  const [id, clueRu, clueEn, contextRu, contextEn, contrastRu, contrastEn] = line.split('|');
  return [Number(id), {
    clue: [clueRu, clueEn],
    paragraphs: [[contextRu, contextEn], [contrastRu, contrastEn]],
    sources: additionalSources[id] || []
  }];
}));
